#!/usr/bin/env python3
"""Rebuild the checked-in documentation bundle from its declared sources."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCES = ['README.md', 'docs/getting-started.md', 'docs/guide.md', 'docs/api.md',
           'docs/roadmap-api.md', 'docs/ROADMAP.md', 'docs/media-support.md',
           'docs/troubleshooting.md', 'AGENTS.md', 'CHANGELOG.md']

def render():
    parts = ['# tgcalls-js — full documentation\n\n'
             'Generated by `python3 scripts/generate-docs.py`; source files are listed in that script.\n']
    for source in SOURCES:
        parts.append(f'\n<!-- ===== {source} ===== -->\n\n{(ROOT / source).read_text().rstrip()}\n')
    return '\n'.join(parts)

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    result = render()
    target = ROOT / 'llms-full.txt'
    if args.check:
        if target.read_text() != result:
            raise SystemExit('llms-full.txt is stale; run python3 scripts/generate-docs.py')
        print('Documentation bundle matches declared sources.')
    else:
        target.write_text(result)
        print('Updated llms-full.txt from declared documentation sources.')
